WITH gaps AS (SELECT *, CASE WHEN LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) IS NULL OR event_time > LAG(event_time) OVER (PARTITION BY page ORDER BY event_time, id) + INTERVAL 90 DAYS THEN 1 ELSE 0 END AS is_new_session FROM web_events), islands AS (SELECT *, SUM(is_new_session) OVER (PARTITION BY page ORDER BY event_time, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS burst_id FROM gaps) SELECT CASE WHEN is_new_session >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END AS is_new_session_tier, CASE WHEN duration_sec >= 458 THEN 'LARGE' ELSE 'SMALL' END AS duration_sec_tier, SUM(CASE WHEN event_type = 'purchase' THEN burst_id ELSE 0 END) AS purchase_burst_id, BIT_AND(duration_sec) AS duration_sec_bit_and, GROUPING(CASE WHEN is_new_session >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END) AS grouping_level FROM islands GROUP BY ROLLUP (CASE WHEN is_new_session >= 1 THEN 'PREMIUM' ELSE 'STANDARD' END, CASE WHEN duration_sec >= 458 THEN 'LARGE' ELSE 'SMALL' END) ORDER BY is_new_session_tier DESC
